import functools
import time

def log_calls(func):
    @functools.wraps(func)
    def wrapper(*args, **kwargs):
        start = time.time()
        print(f'Calling {func.__name__}({args}, {kwargs})')
        result = func(*args, **kwargs)
        elapsed = time.time() - start
        print(f'{func.__name__} returned {result} in {elapsed:.3f}s')
        return result
    return wrapper

@log_calls
def add(a, b):
    return a + b

